IF to_regprocedure('component_expresses(text, jsonb)') IS NULL THEN RAISE EXCEPTION '592: component_expresses does not exist — apply 591 first'; END IF;
-- listing: - [{{.function}}] {{.display_name}}: {{.description}}{{if .expresses}} [expresses: {{.expresses}}]{{else}} [prose only]{{end}}
-- header gains one paragraph explaining the vocabulary and tying structure to promise

-- pre-state per field: exactly one active row, type='text', source='llm', not already html
UPDATE content_components SET input_schema = jsonb_set(jsonb_set(input_schema,'{fields,content,type}','"html"'::jsonb),'{fields,content,llm_guidance}', to_jsonb($g$... Use <h3> for a subheading each time the material turns; <ul>/<ol> with <li> wherever the content is genuinely enumerable; <strong> for the term a reader is scanning for; <table> only when the data really is tabular. Do not pad to earn a list. Never <h1>/<h2>, and never emit <img>, <figure>, <iframe>, form controls, inputs, buttons, element ids, class attributes, inline styles or <script>$g$::text)) WHERE function='generic-text-block' AND is_active;

-- VERIFY reads the LITERAL back, because no downstream check ever could:
IF t IS DISTINCT FROM 'html' THEN RAISE EXCEPTION '594 VERIFY: %.content reads back type=% — expected the literal html (DeclaredTypeSatisfied is default-TRUE and would never surface a typo)', r.fn, t; END IF;
-- plus: sibling fields survived, article-body kept its own proven wording, report-dossier untouched
